/usr/bin/bash -lc "node --input-type=module <<'EOF'
import {DatabaseSync} from 'node:sqlite';
import {readFileSync} from 'node:fs';
import {reserve,cancel} from './src/service.ts';
const db=new DatabaseSync(':memory:');
db.exec(readFileSync('./migrations/001_inventory.sql','utf8'));db.exec(readFileSync('./migrations/002_reservations.sql','utf8').split('-- down')[0].replace('-- up',''));
db.prepare('INSERT INTO inventory VALUES(?,?,?,?)').run('t','A',5,100);db.prepare('INSERT INTO inventory VALUES(?,?,?,?)').run('u','A',9,999);
let a=reserve(db,{tenantId:'t',requestId:'x',items:[{sku:'A',quantity:2},{sku:'A',quantity:1}]});
if(a.totalCents"'!==300||reserve(db,{tenantId:'"'t',requestId:'x',items:[{sku:'A',quantity:99}]}).totalCents"'!==300) throw Error('"'receipt');
if(db.prepare(\"select stock from inventory where tenant_id='t'\").get().stock"'!==2)throw Error('"'debit');
if(cancel(db,'u','x')"'!==false||cancel(db,'"'t','x')"'!==true||cancel(db,'"'t','x')"'!==false)throw Error('"'cancel');
if(db.prepare(\"select stock from inventory where tenant_id='t'\").get().stock"'!==5)throw Error('"'restore');
try{reserve(db,{tenantId:'t',requestId:'bad',items:[{sku:'A',quantity:6}]});throw Error('expected');}catch(e){if(e.message==='expected')throw e;}
if(db.prepare(\"select stock from inventory where tenant_id='t'\").get().stock"'!==5)throw Error('"'rollback');
console.log('focused checks passed');
EOF"

